function nonNegativeInt(value: number, field: string): number { if (!Number.isSafeInteger(value) || value < 0) throw new BiddingSupervisorError("INVALID_INPUT", `${field} must be a non-negative safe integer`); return value; }
function positiveNumber(value: number, field: string): number { if (!Number.isFinite(value) || value <= 0) throw new BiddingSupervisorError("INVALID_INPUT", `${field} must be finite and positive`); return value; }
function step(value: number, field: string): number { if (!Number.isFinite(value) || value <= 0 || value > 0.25) throw new BiddingSupervisorError("INVALID_INPUT", `${field} must be greater than 0 and at most 0.25`); return value; }
