function isJson(value: unknown): value is JsonValue { if (value === null || typeof value === "string" || typeof value === "boolean") return true; if (typeof value === "number") return Number.isFinite(value); if (Array.isArray(value)) return value.every(isJson); if (!value || typeof value !== "object") return false; return Object.values(value as Record<string, unknown>).every(isJson); }
function json(value: unknown, field: string): JsonValue { if (!isJson(value)) throw new BiddingSupervisorError("INTEGRITY_FAILURE", `${field} is not finite JSON`); return value; }
function obj(value: JsonValue | undefined, field: string): Record<string, JsonValue> { if (!value || typeof value !== "object" || Array.isArray(value)) throw new BiddingSupervisorError("INTEGRITY_FAILURE", `${field} must be an object`); return value as Record<string, JsonValue>; }
function stringProp(record: ObjectRecord, key: string): string { const v = record.properties[key]; if (typeof v !== "string" || !v) throw new BiddingSupervisorError("INTEGRITY_FAILURE", `record ${record.id} has invalid ${key}`); return v; }
