function payload(run: RunRecord): RunPayload { return { mode: run.mode, direction: run.direction, reason: run.reason, windowStart: run.windowStart, windowEnd: run.windowEnd, campaignSnapshot: run.campaignSnapshot, portfolioSnapshot: run.portfolioSnapshot, businessSnapshot: run.businessSnapshot, evidence: run.evidence, action: run.action, receipt: run.receipt, errorCode: run.errorCode }; }
