    const campaign = await this.googleAds.getCampaignSnapshot(customerId, campaignId, window.startMs, window.endMs); const campaignQuery: BusinessProfitabilityQuery = { customerId, scopeKind: "CAMPAIGN", scopeId: campaignId, windowStart: window.start, windowEnd: window.end }; const campaignBusiness = Object.freeze({ ...(await this.business.getProfitability(campaignQuery)) }); const campaignFresh = validateBusiness(campaignBusiness, campaignQuery, nowMs, this.policy); const campaignEvidence = evidence(campaign, campaignBusiness);
    let portfolio: GoogleAdsPortfolioSnapshot | null = null; let portfolioBusiness: BusinessProfitabilitySnapshot | null = null; let portfolioEvidence: BiddingSupervisorEvidence | null = null; let portfolioFresh: "FRESH" | "STALE" | null = null; if (campaign.portfolioBiddingStrategyResourceName) { portfolio = await this.googleAds.getPortfolioSnapshot(customerId, campaign.portfolioBiddingStrategyResourceName, window.startMs, window.endMs); const query: BusinessProfitabilityQuery = { customerId, scopeKind: "BIDDING_STRATEGY", scopeId: portfolio.strategyId, windowStart: window.start, windowEnd: window.end }; portfolioBusiness = Object.freeze({ ...(await this.business.getProfitability(query)) }); portfolioFresh = validateBusiness(portfolioBusiness, query, nowMs, this.policy); portfolioEvidence = evidence(portfolio, portfolioBusiness); }
